  ('uncomtrade-ar-lote6-2024', 'UN Comtrade: comercio exterior de Argentina HS 380610/380510 (Colofonia/Trementina), 320110 (Quebracho), 150920/150990 (Oliva) y 300490/293399 (Farmoquímica) 2024', 'UN Comtrade (Naciones Unidas)', 'oficial', 'https://comtradeapi.un.org/public/v1/preview/C/A/HS?reporterCode=32&period=2024&partnerCode=0&partner2Code=0&customsCode=C00&motCode=0&cmdCode=380610,380510,320110,150920,150910,150990,300490,293399', '2026-11-26', 'sha256:04ad52400bfec2549c6e3059edcbb9e1d787b08617dc20d2dac1484b2b47ec98', NULL, 'Flujos oficiales 2024 de colofonia (8.714 t), trementina (5.043 t), extracto de quebracho (11.109 t), aceite de oliva virgen extra HS 1509.20 (18.140 t) y farmoquímica.'),
  ('gruposanfrancisco-web-2026', 'Portal institucional Grupo San Francisco S.A. (Planta Resinera Gobernador Virasoro, Corrientes)', 'Grupo San Francisco S.A.', 'empresa', 'https://gruposanfrancisco.com.ar/', '2026-11-26', 'sha256:d336759d72411d4f455a5a8d5b61955d74381d1b4433c2654dcad2fc59b6215f', NULL, 'Productor forestoquímico sobre RN 14 Km 754 (Gobernador Virasoro, Corrientes): declara 13.000 t/año de miera de pino destilada en colofonia y trementina.'),
  ('unitan-web-2026', 'Portal institucional Unitán S.A.I.C.A. (Extracto de quebracho y especialidades naturales en Formosa)', 'Unitán S.A.I.C.A.', 'empresa', 'https://www.unitan.net/', '2026-11-26', 'sha256:f518159e3922bf613673d1cb3eb08c56f6e129fdac00d70b3bfa584ef26d7f11', NULL, 'Productor argentino líder de extractos tánicos de quebracho colorado (Schinopsis balansae) con planta industrial en la ciudad de Formosa y capacidad conjunta de 40.000 t/año.'),
  ('valledelapuerta-web-2026', 'Portal institucional Valle de la Puerta S.A. (Almazara Vichigasta, Chilecito, La Rioja)', 'Valle de la Puerta S.A.', 'empresa', 'https://valledelapuerta.com.ar/', '2026-11-26', 'sha256:c9f1998a5b29dfb846397cf8fd41563719c832250cabab4725a0d01ebeefbfbf', NULL, 'Finca y planta elaboradora de aceite de oliva virgen extra sobre RN 74 Km 1186 (Vichigasta, Chilecito, La Rioja); declara 1.400 t/año de aceite.'),
  ('agroaceitunera-web-2026', 'Portal institucional Agro Aceitunera S.A. / Nucete (Plantas Aimogasta y Chilecito, La Rioja)', 'Agro Aceitunera S.A.', 'empresa', 'https://agroaceitunera.com.ar/', '2026-11-26', 'sha256:21cb141ab44abd3a7e8c7be0057e4f929a9ba35f497abc1832ba7b70c2eb2057', NULL, 'Complejo olivícola en Aimogasta (Depto. Arauco, La Rioja) con capacidad de molienda declarada de 200 t/día de aceitunas.'),
  ('foa-web-2026', 'Federación Olivícola Argentina (FOA): cadena nacional del aceite de oliva y polo riojano', 'Federación Olivícola Argentina (FOA)', 'tecnica', 'https://federacionolivicolaargentina.com.ar/', '2026-11-26', 'sha256:e3729256698dc15c06d30c39fe6f9f25c354de21023d89bd260c65a7c6fda098', NULL, 'Entidad sectorial de la olivicultura argentina (La Rioja concentra cerca de un tercio de la superficie implantada y eje exportador de aceite de oliva).'),
  ('sde-gob-2026', 'Gobierno de la Provincia de Santiago del Estero: polo productivo algodonero e industrial', 'Gobierno de la Provincia de Santiago del Estero', 'oficial', 'https://sde.gob.ar/', '2026-11-26', 'sha256:67eb4b7e987c6cc654ac20b3855791d371046dbd3972ec57bbf0c8ae4bc1187f', NULL, 'Marco institucional de Santiago del Estero, principal jurisdicción algodonera de Argentina según SAGyP (Quimilí / Depto. Moreno y Bandera / Depto. Belgrano).'),
  ('insudpharma-web-2026', 'Portal corporativo Insud Pharma (Maprimed S.A., Planta Química de APIs en CABA)', 'Insud Pharma / Maprimed S.A.', 'empresa', 'https://www.insudpharma.com/', '2026-11-26', 'sha256:ee07fff97b4fa4611008b7d994cf642f31c76f1a029387a957fa2454cba4b69e', NULL, 'Planta química de síntesis de Ingredientes Farmacéuticos Activos (IFAs/APIs) y centro de I+D de Maprimed S.A. en Av. Directorio 6155 (Comuna 9, CABA), bajo normas GMP/ANMAT/FDA.'),
  ('indec-farmaceutica-2026', 'INDEC: Industria farmacéutica en la Argentina (producción nacional, ventas y comercio exterior)', 'INDEC (República Argentina)', 'oficial', 'https://www.indec.gob.ar/indec/web/Nivel4-Tema-3-6-15', '2026-11-26', 'sha256:9cda8351bdd21468e8ca7187dc330d141ba37992c54acf7aafd4e457874a5c45', NULL, 'Estadística oficial trimestral de la industria farmacéutica argentina (facturación de producción nacional, exportaciones y origen de principios activos).'),
  ('eu-bref-ofc-2006', 'Reference Document on Best Available Techniques for the Manufacture of Organic Fine Chemicals (OFC BREF)', 'Comisión Europea · Joint Research Centre (JRC / EU-BRITE)', 'tecnica', 'https://bureau-industrial-transformation.jrc.ec.europa.eu/reference/manufacture-organic-fine-chemicals', '2026-11-26', 'sha256:e626ff725b025d75d5c7f8f5c66d3603ae3c19e4252fcee386a308e144e49a7a', NULL, 'Referencia técnica BAT para síntesis orgánica fina multipropósito batch (IFAs farmacéuticos, recuperación de solventes, cristalización, secado al vacío y destilación orgánica).'),
  ('eu-bref-tan-2013', 'Best Available Techniques (BAT) Reference Document for the Tanning of Hides and Skins (TAN BREF · Vegetable Tannins)', 'Comisión Europea · Joint Research Centre (JRC / EU-BRITE)', 'tecnica', 'https://bureau-industrial-transformation.jrc.ec.europa.eu/reference/tanning-hides-and-skins', '2026-11-26', 'sha256:00fcedb65645d9f2e754355046e25d6e5788a3664441200b9fcd5fad3a0cfad7', NULL, 'Referencia internacional BAT sobre agentes curtientes vegetales (extracto de quebracho, polifenoles condensados y estándares ambientales de uso industrial).'),
  ('druetta-web-2026', 'Portal institucional Druetta Hnos. S.A. (Planta General Rodríguez, Buenos Aires)', 'Druetta Hnos. S.A.', 'empresa', 'https://www.druetta.com.ar/', '2026-11-27', 'sha256:eb0ee6c4ae621f4c701f4ce06a529ddc45d7cf64324bd8d2c31980849921abaa', NULL, 'Planta industrial en Chaco 1155, Acceso Oeste Km 47, General Rodríguez (Buenos Aires). Predio de 55.000 m2, 11.000 m2 cubiertos, laboratorio propio, ISO 9001:2015 e ISO 14001:2015.'),
  ('druetta-hornos-2026', 'Ficha técnica de Hornos e Instalaciones de Galvanizado (Druetta Hnos. S.A.)', 'Druetta Hnos. S.A.', 'empresa', 'https://www.druetta.com.ar/instalaciones4.html', '2026-11-27', 'sha256:42167c1b8abd99865a7b4584942733699aed7ff57cc2df388da60857722f5de7', NULL, 'Horno 1 de 13,0 x 1,8 x 3,0 m para inmersión única de grandes estructuras y Horno 2 de 4,5 x 1,4 x 2,2 m para piezas menores y centrifugado a 450 °C con control automático.'),
  ('druetta-procesos-2026', 'Descripción oficial de etapas del proceso de Galvanizado por Inmersión en Caliente (Druetta Hnos. S.A.)', 'Druetta Hnos. S.A.', 'empresa', 'https://www.druetta.com.ar/galvanizado3.html', '2026-11-27', 'sha256:78b05da2694e9bb944dc252146eb27b48ec63193936bd19d43aa8c1aa33ec5f4', NULL, 'Secuencia completa verificada: desengrase alcalino, enjuague, decapado ácido, enjuague, flux, secado (60-100 °C), baño de zinc fundido (450 °C), enfriamiento e inspección.'),
  ('eu-bref-fmp-2022', 'EU BAT Reference Document (BREF) for the Ferrous Metals Processing Industry (FMP)', 'Comisión Europea (JRC / EU-BRITE)', 'tecnica', 'https://bureau-industrial-transformation.jrc.ec.europa.eu/reference/ferrous-metals-processing-industry', '2026-11-27', 'sha256:8248df53c2e5bc1b07c8fc357085b57bfdb9192fd64d22757917f96c13dcea8b', NULL, 'Documento técnico de referencia europeo para batch galvanizing (galvanizado por inmersión en caliente), decapado en HCl, fluxado, captación de humos, tratamiento de efluentes y recuperación de zinc.'),
  ('uncomtrade-ar-lote7-2023', 'UN Comtrade: comercio exterior de Argentina HS 7901.11/7901.12 (Zinc sin alear), 7210.49, 7308.90 (Estructuras) y 2806.10 (HCl) 2023', 'UN Comtrade (Naciones Unidas)', 'oficial', 'https://comtradeapi.un.org/public/v1/preview/C/A/HS?reporterCode=32&period=2023&partnerCode=0&partner2Code=0&customsCode=C00&motCode=0&cmdCode=790111,790112,721049,730890,280610', '2026-11-27', 'sha256:dc1b298e30a29c9d141a6857192f58d2ba5a0cdba045c292e582d76c93cdac1c', NULL, 'Datos oficiales aduaneros 2023 para zinc en bruto sin alear (insumo directo del galvanizado) y estructuras metálicas de acero en Argentina.'),
  ('uncomtrade-ar-lote7-2024', 'UN Comtrade: comercio exterior de Argentina HS 7901.11/7901.12 (Zinc sin alear), 7210.49, 7308.90 (Estructuras) y 2806.10 (HCl) 2024', 'UN Comtrade (Naciones Unidas)', 'oficial', 'https://comtradeapi.un.org/public/v1/preview/C/A/HS?reporterCode=32&period=2024&partnerCode=0&partner2Code=0&customsCode=C00&motCode=0&cmdCode=790111,790112,721049,730890,280610', '2026-11-27', 'sha256:93dfbdfc57f8246c22b9e8a0c42d086a914a9c5f50a1b0601d1b6eefc38dbd7c', NULL, 'Datos oficiales aduaneros 2024 para zinc en bruto sin alear (HS 7901.11/7901.12) y estructuras metálicas de acero (HS 7308.90) en Argentina.')
