  ('46', 'La Rioja', 'AR-F', 'NOA', 'completa', 'Polo olivícola industrial de aceite de oliva virgen extra en Chilecito y Arauco (Valle de la Puerta y Agro Aceitunera Nucete) verificado con FOA, EU FDM BREF y UN Comtrade HS 1509.20/1509.10.'),
  ('50', 'Mendoza', 'AR-M', 'Cuyo', 'completa', 'Polo refinador y de polipropileno en Luján de Cuyo (YPF CILC y Petrocuyo) verificado con EU POL BREF, Petrocuyo y UN Comtrade HS 3902.10.'),
  ('54', 'Misiones', 'AR-N', 'NEA', 'completa', 'Polo celulósico Kraft blanqueado de fibra larga (Puerto Esperanza, Depto. Iguazú) verificado con Arauco, AFCP y UN Comtrade HS 4703.21.'),
  ('58', 'Neuquén', 'AR-Q', 'Patagonia', 'completa', 'Cadena de metanol desde gas natural (Complejo Industrial Plaza Huincul, Depto. Confluencia) verificada con IPCC Cap. 3.9, EU LVOC BREF, YPF y UN Comtrade HS 2905.11.'),
  ('62', 'Río Negro', 'AR-R', 'Patagonia', 'completa', 'Polo químico de carbonato de sodio / Soda Solvay (San Antonio Oeste, ALPAT) verificado con EU LVIC-S BREF, IPCC Cap. 2, USGS MCS 2025 y UN Comtrade HS 2836.20.'),
  ('66', 'Salta', 'AR-A', 'NOA', 'completa', 'Cadena de litio (Salar del Rincón, Depto. Los Andes) verificada con USGS MCS 2025, UN Comtrade y Rio Tinto.'),
  ('70', 'San Juan', 'AR-J', 'Cuyo', 'completa', 'Polo calero industrial de Los Berros (Depto. Sarmiento) verificado con IPCC Cap. 2.3, EU CLM BREF, Caleras San Juan, USGS MCS 2025 y UN Comtrade HS 2522.10.'),
  ('74', 'San Luis', 'AR-D', 'Cuyo', 'completa', 'Planta integrada de clínker y cemento Portland en La Calera (Depto. Belgrano, Cementos Avellaneda) verificada con IPCC Cap. 2.2, EU CLM BREF, AFCP Cemento, USGS MCS 2025 y UN Comtrade HS 2523.'),
  ('78', 'Santa Cruz', 'AR-Z', 'Patagonia', 'completa', 'Macizo del Deseado (oro y plata en lingote doré en Magallanes y Lago Buenos Aires) verificado con USGS MCS 2025, Cerro Vanguardia, CAEM y UN Comtrade HS 7108.12/7106.91.'),
  ('82', 'Santa Fe', 'AR-S', 'Centro', 'completa', 'Complejo oleaginoso de soja y polo de biodiésel (San Lorenzo, Timbúes y Rosario) verificados con SAGyP, Secretaría de Energía, Renova, Molinos Agro y UN Comtrade.'),
  ('86', 'Santiago del Estero', 'AR-G', 'NOA', 'completa', 'Principal cuenca algodonera de Argentina (Depto. Moreno y Depto. Belgrano; Desmotadora Quimilí de LDC) verificada con SAGyP Estimaciones Agrícolas 2026 y UN Comtrade HS 5201.00.'),
  ('90', 'Tucumán', 'AR-T', 'NOA', 'completa', 'Complejo sucroalcoholero de bioetanol y azúcar de caña (Depto. Cruz Alta) verificado con Secretaría de Energía, Centro Azucarero Argentino y UN Comtrade HS 2207.10/1701.99.'),
  ('94', 'Tierra del Fuego, Antártida e Islas del Atlántico Sur', 'AR-V', 'Patagonia', 'completa', 'Complejo gasífero y de fraccionamiento criogénico de GLP en Cuenca Austral (Río Grande, TotalEnergies) verificado con ENARGAS, EU REF BREF y UN Comtrade HS 2711.12/2711.13.')
INSERT INTO public.departamentos (departamento_id, provincia_id, nombre, tipo_zona, tiene_datos_confiables, cobertura_datos, nota_cobertura) VALUES
  ('06056', '06', 'Bahía Blanca', 'polo_industrial', TRUE, 'completa', 'Polo petroquímico (Dow, Unipar Indupa) y fertilizantes nitrogenados (Profertil) verificados con fuentes oficiales, IPCC y UN Comtrade.'),
  ('10028', '10', 'Antofagasta de la Sierra', 'minero', TRUE, 'completa', 'Salar del Hombre Muerto (Catamarca): Planta Fénix (Rio Tinto) operando Extracción Directa de Litio (DLE por adsorción) desde 1997 (32 ktpa LCE).'),
  ('22021', '22', 'Comandante Fernández', 'agro', TRUE, 'completa', 'Presidencia Roque Sáenz Peña (Chaco): polo histórico de desmote, hilatura e investigación algodonera.'),
  ('22098', '22', 'Mayor Luis J. Fontana', 'agro', TRUE, 'completa', 'Villa Ángela (Chaco): primer departamento productor de algodón en bruto de la provincia (SAGyP 2023/24).'),
  ('22105', '22', '9 de Julio', 'agro', TRUE, 'completa', 'Las Breñas (Chaco): núcleo algodonero y desmotadoras industriales (Buyatti S.A.I.C.A.).'),
  ('26007', '26', 'Biedma', 'polo_industrial', TRUE, 'completa', 'Puerto Madryn: sede del único complejo productor de aluminio primario del país (Parque Industrial Pesado y Muelle Almirante Storni).'),
  ('38084', '38', 'Susques', 'minero', TRUE, 'completa', 'Salares de Olaroz y Cauchari-Olaroz (Jujuy): ruta evaporítica en piletas solares hacia carbonato de litio.'),
  ('66105', '66', 'Los Andes', 'minero', TRUE, 'parcial', 'Puna salteña (Salar del Rincón): planta inicial DLE (3.000 t/año desde nov. 2024) y expansión DLE comercial hacia 60 ktpa LCE.'),
  ('82084', '82', 'Rosario', 'agro', TRUE, 'completa', 'Nodo portuario e industrial del Gran Rosario vinculado a molienda de soja y biodiésel (SAGyP, Secretaría de Energía y UN Comtrade).'),
  ('82119', '82', 'San Lorenzo', 'polo_industrial', TRUE, 'completa', 'Cordón industrial Up-River (Timbúes y San Lorenzo): mayor polo mundial de molienda de soja y biodiésel (Renova, Molinos Agro).'),
  ('58035', '58', 'Confluencia', 'energetico', TRUE, 'completa', 'Plaza Huincul y cuenca gasífera neuquina: sede de la principal planta de metanol a partir de gas natural del país (YPF CIPH).'),
  ('50063', '50', 'Luján de Cuyo', 'polo_industrial', TRUE, 'completa', 'Polo Petroquímico y Refinador mendocino: Complejo Industrial YPF (FCC y propileno) integrado con Petrocuyo (polipropileno).'),
  ('14098', '14', 'Río Cuarto', 'agro', TRUE, 'completa', 'Núcleo maicero del sur cordobés: sede de Bio4 Argentina (molienda seca de maíz, bioetanol anhidro y burlanda DDGS).'),
  ('14042', '14', 'General San Martín', 'agro', TRUE, 'completa', 'Villa María (Córdoba): biorrefinería cooperativa ACA Bio para bioetanol anhidro de maíz y recuperación de CO2.'),
  ('90014', '90', 'Cruz Alta', 'agro', TRUE, 'completa', 'Cordón sucroalcoholero del este tucumano (La Florida / Banda del Río Salí): molienda de caña, destilerías y deshidratadoras de bioetanol.'),
  ('62077', '62', 'San Antonio', 'polo_industrial', TRUE, 'completa', 'Sede de ALPAT en Punta Delgado (San Antonio Oeste), única planta Solvay de carbonato de sodio de Sudamérica.'),
  ('70105', '70', 'Sarmiento', 'minero', TRUE, 'completa', 'Polo calero de Los Berros, principal concentrador argentino de cal viva (CaO) e hidratada para minería y siderurgia.'),
  ('78042', '78', 'Magallanes', 'minero', TRUE, 'completa', 'Área Puerto San Julián / Cerro Vanguardia (oro y plata en lingote doré en el Macizo del Deseado).'),
  ('78035', '78', 'Lago Buenos Aires', 'minero', TRUE, 'completa', 'Área Perito Moreno / Cerro Negro (operación subterránea y planta de lixiviación de oro y plata).'),
  ('54063', '54', 'Iguazú', 'agro', TRUE, 'completa', 'Puerto Esperanza, sede de la planta de celulosa Kraft blanqueada de fibra larga de pino de Arauco Argentina.'),
  ('54077', '54', 'Libertador General San Martín', 'agro', TRUE, 'completa', 'Corredor foresto-industrial del Alto Paraná misionero (abastecimiento de madera de pino y pasta Kraft).'),
  ('94008', '94', 'Río Grande', 'polo_industrial', TRUE, 'completa', 'Cabecera terrestre de la Cuenca Austral (Río Cullen / Cañadón Alfa): acondicionamiento de gas natural y fraccionamiento de GLP y gasolina natural.'),
  ('42007', '42', 'Atreucó', 'minero', TRUE, 'completa', 'Salinas Grandes de Hidalgo (área Macachín / Hidalgo), mayor centro histórico de cosecha y refinación de sal industrial NaCl de Argentina.'),
  ('42077', '42', 'Hucal', 'minero', TRUE, 'completa', 'Salina Colorada Grande (General San Martín), cuenca evaporítica pampeana de cloruro de sodio para industria química y ganadera.'),
  ('74014', '74', 'Belgrano', 'minero', TRUE, 'completa', 'Localidad de La Calera, sede de la planta integrada de clínker y cemento Portland vía seca de Cementos Avellaneda S.A.'),
  ('30015', '30', 'Concordia', 'agro', TRUE, 'completa', 'Eje industrial citrícola de Entre Ríos para extracción en frío de aceite esencial D-limoneno y evaporación de jugo concentrado.'),
  ('30028', '30', 'Federación', 'agro', TRUE, 'completa', 'Cuenca productora primaria de naranjas y mandarinas que abastece a las plantas de jugos concentrados y aceites esenciales de Entre Ríos.'),
  ('02063', '02', 'Comuna 9', 'polo_industrial', TRUE, 'completa', 'Barrio de Mataderos (Av. Directorio 6155): sede de la planta química de síntesis de Ingredientes Farmacéuticos Activos (IFAs) y centro de I+D de Maprimed S.A. (Insud Pharma).'),
  ('18168', '18', 'Santo Tomé', 'agro', TRUE, 'completa', 'Eje forestoquímico Gobernador Virasoro y Santo Tomé: extracción de miera de Pinus elliottii y destilación industrial a colofonia y trementina (Grupo San Francisco).'),
  ('34014', '34', 'Formosa', 'polo_industrial', TRUE, 'completa', 'Ciudad de Formosa: sede de la planta de Unitán S.A.I.C.A. para extracción acuosa y secado spray de extracto de quebracho colorado y bioactivos tánicos.'),
  ('46007', '46', 'Arauco', 'agro', TRUE, 'completa', 'Aimogasta (Capital Nacional del Olivo): polo de molienda e industrialización olivícola de Agro Aceitunera S.A. (Nucete) y almazaras de variedad Arauco.'),
  ('46042', '46', 'Chilecito', 'agro', TRUE, 'completa', 'Valle de Vichigasta y Chilecito: complejo agroindustrial de Valle de la Puerta S.A. para extracción continua en frío de aceite de oliva virgen extra.'),
  ('86042', '86', 'Belgrano', 'agro', TRUE, 'completa', 'Bandera (Santiago del Estero): primer departamento productor de algodón en bruto de la provincia en campaña 2024/25 (72.120 t según SAGyP).'),
  ('86119', '86', 'Moreno', 'agro', TRUE, 'completa', 'Quimilí (Santiago del Estero): núcleo algodonero provincial (95.887 t en 2023/24 según SAGyP) y planta desmotadora ampliada de Louis Dreyfus Company (60.000 t/año).'),
  ('06364', '06', 'General Rodríguez', 'polo_industrial', TRUE, 'completa', 'Acceso Oeste Km 47 (Chaco 1155, General Rodríguez): sede de la planta industrial de galvanizado por inmersión en caliente de Druetta Hnos. S.A. (hornos de 13 m y 4,5 m a 450 °C, ISO 9001 e ISO 14001).')
INSERT INTO public.productos (producto_id, nombre, categoria, formula_quimica, icono_id, descripcion_corta, mdx_slug, estado_mvp) VALUES
  ('aluminio', 'Aluminio primario', 'metalurgia', 'Al', 'aluminio-lingote', 'Metal ligero obtenido en Puerto Madryn por reducción electrolítica Hall-Héroult de alúmina importada con energía hidroeléctrica, térmica y eólica.', 'aluminio', 'validado'),
  ('litio', 'Carbonato de litio', 'mineria_quimica', 'Li2CO3', 'litio-salmuera', 'Carbonato de litio obtenido por evaporación solar y precipitación química en los salares de la Puna (Jujuy, Catamarca y Salta).', 'litio', 'validado'),
  ('urea', 'Urea y fertilizantes nitrogenados', 'fertilizantes', 'CO(NH2)2', 'urea-prill', 'Fertilizante nitrogenado sintetizado a partir de gas natural, agua y aire (reformado, Haber-Bosch y granulación) en Bahía Blanca.', 'urea', 'validado'),
  ('algodon', 'Algodón y fibra textil', 'agroindustria', NULL, 'algodon-fibra', 'Fibra de celulosa obtenida por desmote mecánico y refinación química húmeda en Santiago del Estero y Chaco.', 'algodon', 'validado'),
  ('soja', 'Soja y derivados oleaginosos', 'agroindustria', NULL, 'soja-molienda', 'Molienda de poroto y extracción continua por solvente (hexano) para harina proteica, aceite crudo y lecitina en el Up-River santafesino.', 'soja', 'validado'),
  ('petroquimica', 'Petroquímica básica y polietilenos', 'petroquimica', 'C2H4', 'petroquimica-cracker', 'Craqueo térmico con vapor de etano (steam cracking) y polimerización a polietileno y PVC en el Polo Petroquímico de Bahía Blanca.', 'petroquimica', 'validado'),
  ('biodiesel', 'Biodiésel (FAME)', 'bioenergia', 'RCOOCH3', 'biodiesel-ester', 'Ésteres metílicos de ácidos grasos (FAME) obtenidos por transesterificación alcalina de aceite de soja con metanol en San Lorenzo y Gran Rosario.', 'biodiesel', 'validado'),
  ('metanol', 'Metanol', 'petroquimica', 'CH3OH', 'metanol-sintesis', 'Síntesis catalítica de metanol grado químico desde gas natural neuquino en Plaza Huincul (insumo clave para biodiésel, resinas y formaldehído).', 'metanol', 'validado'),
  ('polipropileno', 'Polipropileno', 'petroquimica', '(C3H6)n', 'polipropileno-pellet', 'Polimerización catalítica de propileno proveniente de refinación FCC en el Polo Industrial de Luján de Cuyo (Mendoza).', 'polipropileno', 'validado'),
  ('bioetanol-maiz', 'Bioetanol de maíz', 'bioenergia', 'C2H5OH', 'bioetanol-maiz', 'Biorrefinerías de molienda seca de maíz en Córdoba: hidrólisis enzimática, fermentación, deshidratación con tamices moleculares y burlanda DDGS.', 'bioetanol-maiz', 'validado'),
  ('bioetanol-cana', 'Bioetanol y azúcar de caña', 'bioenergia', 'C2H5OH / C12H22O11', 'bioetanol-cana', 'Complejos sucroalcoholeros de Tucumán: trapiche, cristalización de azúcar, fermentación de melazas y jugo a etanol anhidro con cogeneración desde bagazo.', 'bioetanol-cana', 'validado'),
  ('soda-solvay', 'Carbonato de sodio (Soda Solvay)', 'mineria_quimica', 'Na2CO3', 'soda-solvay', 'Carbonato de sodio sintético producido en San Antonio Oeste por proceso Solvay a partir de salmuera y caliza, insumo crítico del litio y del vidrio.', 'soda-solvay', 'validado'),
  ('cal-industrial', 'Cal industrial (CaO)', 'mineria_quimica', 'CaO', 'cal-industrial', 'Óxido de calcio obtenido por calcinación térmica de caliza en Los Berros (San Juan), insumo clave para minería metalífera, litio y siderurgia.', 'cal-industrial', 'validado'),
  ('oro-plata', 'Oro y plata (lingote doré)', 'metalurgia', 'Au / Ag', 'oro-plata', 'Metales preciosos recuperados por lixiviación cianurada, precipitación y fundición doré en el Macizo del Deseado (Santa Cruz).', 'oro-plata', 'validado'),
  ('celulosa-kraft', 'Celulosa Kraft blanqueada', 'agroindustria', '(C6H10O5)n', 'celulosa-kraft', 'Pulpa química de fibra larga de pino obtenida por cocción Kraft al sulfato, blanqueo ECF y ciclo cerrado de recuperación en Misiones.', 'celulosa-kraft', 'validado'),
  ('glp-gas-natural', 'Gas licuado de petróleo (GLP)', 'petroquimica', 'C3H8 / C4H10', 'glp-gas-natural', 'Propano, butano y gasolina natural recuperados por expansión criogénica desde gas húmedo de la Cuenca Austral en Río Grande (Tierra del Fuego).', 'glp-gas-natural', 'validado'),
  ('sal-industrial', 'Sal industrial (NaCl)', 'mineria_quimica', 'NaCl', 'sal-industrial', 'Cloruro de sodio de alta pureza cosechado en las salinas evaporíticas de La Pampa, lavado contracorriente y refinado para química cloro-soda y alimentación.', 'sal-industrial', 'validado'),
  ('cemento-clinker', 'Cemento Portland (clínker)', 'mineria_quimica', 'Ca3SiO5 / Ca2SiO4', 'cemento-clinker', 'Clínker hidráulico producido por calcinación a 1.450 °C en horno rotativo vía seca con precalcinador en La Calera (San Luis) y molienda final con yeso.', 'cemento-clinker', 'validado'),
  ('citricos-limoneno', 'Aceite esencial cítrico y jugo concentrado', 'agroindustria', 'C10H16', 'citricos-limoneno', 'Extracción en frío de D-limoneno desde cáscara cítrica, evaporación multiefecto TASTE de jugos y secado de pectinas en Concordia (Entre Ríos).', 'citricos-limoneno', 'validado'),
  ('resina-colofonia', 'Resina de pino, colofonia y trementina', 'agroindustria', 'C20H30O2 / C10H16', 'resina-colofonia', 'Destilación térmica y fraccionamiento por arrastre de vapor de oleorresina de Pinus elliottii en Corrientes para obtener colofonia y trementina.', NULL, 'validado'),
  ('tanino-quebracho', 'Extracto de quebracho (tanino vegetal)', 'agroindustria', '(C15H12O6)n', 'tanino-quebracho', 'Extracción sólido-líquido contracorriente, evaporación multiefecto y secado spray de polifenoles de Schinopsis balansae en Formosa.', NULL, 'validado'),
  ('aceite-oliva', 'Aceite de oliva virgen extra', 'agroindustria', 'C57H104O6', 'aceite-oliva', 'Extracción físico-química continua en frío de dos fases (malaxado y centrifugación decanter) en los valles de Chilecito y Arauco (La Rioja).', NULL, 'validado'),
  ('farmoquimica-ifa', 'Farmoquímica y principios activos (IFAs)', 'petroquimica', 'API / GMP', 'farmoquimica-ifa', 'Síntesis orgánica fina multipropósito en reactores batch GMP, cristalización, centrifugación y secado al vacío de principios activos en CABA.', NULL, 'validado'),
  ('galvanizado-caliente', 'Galvanizado por inmersión en caliente', 'metalurgia', 'Fe-Zn (Zn 450 °C)', 'galvanizado-caliente', 'Recubrimiento anticorrosivo metalúrgico del acero por inmersión en baño de zinc fundido a 450 °C tras desengrase alcalino, decapado en HCl y fluxado en General Rodríguez (Buenos Aires).', NULL, 'validado')
