  ('cal-p1-cantera', 'cal-industrial-calcinacion', 1, 'Extracción, trituración y clasificación de caliza', 'materia_prima', NULL, 'Ambiente', '1,0', '[{"especie":"CaCO3 (caliza)","cantidad":1.82,"unidad":"t/t CaO"}]'::jsonb, '[{"especie":"Caliza clasificada (30-90 mm)","cantidad":1.8,"unidad":"t/t CaO"}]'::jsonb, '[{"especie":"Energía mecánica","cantidad":null,"unidad":"kWh/t"}]'::jsonb, '[{"especie":"Finos de caliza","cantidad":0.02,"unidad":"t/t CaO"}]'::jsonb, NULL, 'sin_datos', 'GJ/t', 'La roca caliza de alta ley de Los Berros se tritura y zarandea a granulometría controlada (30-90 mm) para garantizar permeabilidad al gas en el horno.', 80, 180, 2006, 'ipcc-2006-mineral-cap2', 'IPCC 2006 Vol. 3 Cap. 2.3 Lime Production + EU CLM BREF', 'alta'),
  ('cal-p2-precalentamiento', 'cal-industrial-calcinacion', 2, 'Precalentamiento regenerativo de carga', 'preparacion', NULL, '650-800', '1,0', '[{"especie":"Caliza clasificada","cantidad":1.8,"unidad":"t/t CaO"}]'::jsonb, '[{"especie":"Caliza precalentada","cantidad":1.8,"unidad":"t/t CaO"}]'::jsonb, '[{"especie":"Gases calientes del cuba paralelo","cantidad":null,"unidad":"Nm3/t"}]'::jsonb, '[]'::jsonb, NULL, 'sin_datos', 'GJ/t', 'En el horno vertical de doble cuba (PFRK), los gases de escape ceden calor sensible a la caliza descendente antes de la zona de fuego.', 340, 180, 2006, 'ipcc-2006-mineral-cap2', 'IPCC 2006 Vol. 3 Cap. 2.3 Lime Production + EU CLM BREF', 'alta'),
  ('cal-p3-calcinacion', 'cal-industrial-calcinacion', 3, 'Calcinación térmica de caliza a cal viva (CaO)', 'reaccion', 'CaCO3 -> CaO + CO2', '950-1100', '1,0', '[{"especie":"CaCO3","cantidad":1.8,"unidad":"t/t CaO"}]'::jsonb, '[{"especie":"CaO (cal viva)","cantidad":1,"unidad":"t/t CaO"},{"especie":"CO2 de proceso","cantidad":0.785,"unidad":"t/t CaO"}]'::jsonb, '[{"especie":"Gas natural / combustible","cantidad":null,"unidad":"GJ/t"}]'::jsonb, '[{"especie":"CO2 descarbonatación + combustión","cantidad":0.785,"unidad":"t/t CaO"}]'::jsonb, NULL, 'sin_datos', 'GJ/t', 'Reacción endotérmica de descarbonatación en flujo paralelo con alternancia cíclica de quemadores; emite 0,785 t CO2 estequiométrico por tonelada de CaO puro (IPCC Cap. 2.3).', 620, 180, 2006, 'ipcc-2006-mineral-cap2', 'IPCC 2006 Vol. 3 Cap. 2.3 Lime Production + EU CLM BREF', 'alta'),
  ('cal-p4-enfriamiento-molienda', 'cal-industrial-calcinacion', 4, 'Enfriamiento, clasificación y molienda de CaO', 'refinacion', NULL, '60-120', '1,0', '[{"especie":"CaO incandescente","cantidad":1,"unidad":"t/t CaO"}]'::jsonb, '[{"especie":"Cal viva granulada / molida","cantidad":1,"unidad":"t/t CaO"}]'::jsonb, '[{"especie":"Aire de enfriamiento","cantidad":null,"unidad":"Nm3/t"}]'::jsonb, '[{"especie":"Polvo retenido en filtros de mangas","cantidad":null,"unidad":"kg/t"}]'::jsonb, NULL, 'sin_datos', 'GJ/t', 'La cal viva se enfría recuperando calor hacia el aire de combustión, se clasifica por granulometría y se almacena en silos herméticos anti-humedad.', 900, 140, 2006, 'ipcc-2006-mineral-cap2', 'IPCC 2006 Vol. 3 Cap. 2.3 Lime Production + EU CLM BREF', 'alta'),
  ('cal-p5-hidratacion-despacho', 'cal-industrial-calcinacion', 5, 'Hidratación controlada a Ca(OH)2 y despacho', 'producto', 'CaO + H2O -> Ca(OH)2', '90-105', '1,0', '[{"especie":"CaO","cantidad":0.76,"unidad":"t/t Ca(OH)2"},{"especie":"H2O","cantidad":0.25,"unidad":"t/t Ca(OH)2"}]'::jsonb, '[{"especie":"Ca(OH)2 (cal hidratada) y CaO a granel","cantidad":1,"unidad":"t/t"}]'::jsonb, '[{"especie":"Agua desmineralizada","cantidad":0.25,"unidad":"t/t"}]'::jsonb, '[{"especie":"Vapor de agua","cantidad":null,"unidad":"t/t"}]'::jsonb, NULL, 'sin_datos', 'GJ/t', 'Fracción de la cal viva se apaga en hidratadores continuos para obtener hidróxido de calcio fino destinado a minería de litio, potabilización y exportación.', 1180, 180, 2006, 'ipcc-2006-mineral-cap2', 'IPCC 2006 Vol. 3 Cap. 2.3 Lime Production + EU CLM BREF', 'alta'),
  ('oro-p1-molienda', 'oro-plata-lixiviacion-dore', 1, 'Trituración y molienda SAG/bolas de mena', 'preparacion', NULL, 'Ambiente', '1,0', '[{"especie":"Mineral epitermal Au/Ag","cantidad":1000,"unidad":"t mena/lote"}]'::jsonb, '[{"especie":"Pulpa molida (<75 micras)","cantidad":1000,"unidad":"t sólidos"}]'::jsonb, '[{"especie":"Agua de proceso reciclada","cantidad":null,"unidad":"m3/t"},{"especie":"CaO (ajuste pH >10,5)","cantidad":null,"unidad":"kg/t"}]'::jsonb, '[]'::jsonb, NULL, 'sin_datos', 'kWh/t', 'El mineral cuarzoso del Macizo del Deseado se reduce en circuitos de chancado, molinos SAG/bolas e hidrociclones en medio alcalino con cal para liberar oro y plata.', 80, 180, 2026, 'cerro-vanguardia-web-2026', 'cerrovanguardia.com.ar Proceso hidrometalúrgico cianuración + fundición doré', 'alta'),
  ('oro-p2-lixiviacion', 'oro-plata-lixiviacion-dore', 2, 'Lixiviación cianurada agitada con oxígeno', 'reaccion', '4 Au + 8 NaCN + O2 + 2 H2O -> 4 Na[Au(CN)2] + 4 NaOH', '15-25', '1,0', '[{"especie":"Pulpa Au/Ag","cantidad":null,"unidad":"t/h"},{"especie":"NaCN","cantidad":null,"unidad":"kg/t mena"},{"especie":"O2","cantidad":null,"unidad":"Nm3/t"}]'::jsonb, '[{"especie":"Solución rica Na[Au(CN)2] / Na[Ag(CN)2]","cantidad":null,"unidad":"m3/h"}]'::jsonb, '[{"especie":"CaO (control pH 10,5-11)","cantidad":null,"unidad":"kg/t"}]'::jsonb, '[{"especie":"Relaves agotados hacia detoxificación","cantidad":null,"unidad":"t/h"}]'::jsonb, NULL, 'sin_datos', 'kWh/t', 'En tanques agitados aireados (ecuación de Elsner), el oro y la plata forman complejos solubles de aurocianuro y argentocianuro manteniendo pH alcalino seguro.', 360, 180, 2026, 'cerro-vanguardia-web-2026', 'cerrovanguardia.com.ar Proceso hidrometalúrgico cianuración + fundición doré', 'alta'),
  ('oro-p3-precipitacion', 'oro-plata-lixiviacion-dore', 3, 'Clarificación y precipitación Merrill-Crowe', 'separacion', '2 Na[Au(CN)2] + Zn -> 2 Au + Na2[Zn(CN)4]', '20-25', '0,2 (vacío desaireación)', '[{"especie":"Solución rica clarificada","cantidad":null,"unidad":"m3/h"},{"especie":"Zn en polvo","cantidad":null,"unidad":"kg/lote"}]'::jsonb, '[{"especie":"Precipitado metálico Au/Ag","cantidad":null,"unidad":"kg/lote"},{"especie":"Solución estéril reciclada","cantidad":null,"unidad":"m3/h"}]'::jsonb, '[{"especie":"Tierra de diatomeas (filtros)","cantidad":null,"unidad":"kg/lote"}]'::jsonb, '[]'::jsonb, NULL, 'sin_datos', 'kWh/t', 'La solución rica se clarifica y desoxigena al vacío; al inyectar polvo de zinc precipitan el oro y la plata metálicos mientras la solución estéril retorna a lixiviación.', 640, 140, 2026, 'cerro-vanguardia-web-2026', 'cerrovanguardia.com.ar Proceso hidrometalúrgico cianuración + fundición doré', 'alta'),
  ('oro-p4-fundicion-dore', 'oro-plata-lixiviacion-dore', 4, 'Fundición de precipitado y colada de barras doré', 'producto', NULL, '1100-1200', '1,0', '[{"especie":"Precipitado Au/Ag seco","cantidad":null,"unidad":"kg/lote"}]'::jsonb, '[{"especie":"Lingote doré (aleación Au/Ag)","cantidad":null,"unidad":"kg/lote"}]'::jsonb, '[{"especie":"Fundentes (bórax, sílice, nitrato)","cantidad":null,"unidad":"kg/lote"}]'::jsonb, '[{"especie":"Escoria vitrificada (reprocesable)","cantidad":null,"unidad":"kg/lote"}]'::jsonb, NULL, 'sin_datos', 'kWh/kg', 'El precipitado se funde con fundentes en hornos de inducción o basculantes a 1.150 °C para colar barras doré (Au/Ag) destinadas a refinación final y exportación.', 920, 120, 2026, 'cerro-vanguardia-web-2026', 'cerrovanguardia.com.ar Proceso hidrometalúrgico cianuración + fundición doré', 'alta'),
  ('oro-p5-detox-relaves', 'oro-plata-lixiviacion-dore', 5, 'Destrucción de cianuro (INCO SO2/aire) y dique', 'emision', 'CN- + SO2 + O2 + H2O -> CNO- + H2SO4', 'Ambiente', '1,0', '[{"especie":"Relaves con cianuro WAD","cantidad":null,"unidad":"t/h"},{"especie":"SO2 / metabisulfito + aire","cantidad":null,"unidad":"kg/t"}]'::jsonb, '[{"especie":"Relave detoxificado (cianato CNO-)","cantidad":null,"unidad":"t/h"}]'::jsonb, '[{"especie":"CuSO4 catalizador + cal","cantidad":null,"unidad":"kg/t"}]'::jsonb, '[{"especie":"Agua clarificada recuperada","cantidad":null,"unidad":"m3/h"}]'::jsonb, NULL, 'sin_datos', 'kWh/t', 'Antes de enviarse al depósito de colas impermeabilizado, el cianuro libre y disociable se oxida a cianato inocuo mediante el proceso INCO SO2/aire bajo Código Internacional del Cianuro.', 920, 280, 2026, 'cerro-vanguardia-web-2026', 'cerrovanguardia.com.ar Proceso hidrometalúrgico cianuración + fundición doré', 'alta'),
  ('kraft-p1-chipeado', 'celulosa-kraft-blanqueada', 1, 'Descortezado y chipeado de madera de pino', 'materia_prima', NULL, 'Ambiente', '1,0', '[{"especie":"Rollizos de pino (Pinus taeda/elliottii)","cantidad":4.5,"unidad":"m3/t ADt"}]'::jsonb, '[{"especie":"Chips calibrados de fibra larga","cantidad":2.1,"unidad":"t seca/t ADt"}]'::jsonb, '[{"especie":"Energía eléctrica cogenerada","cantidad":null,"unidad":"MWh/t"}]'::jsonb, '[{"especie":"Corteza y aserrín a caldera biomasa","cantidad":0.35,"unidad":"t/t ADt"}]'::jsonb, NULL, 'sin_datos', 'MWh/t', 'Los rollizos forestales de Misiones se descortezan y astillan en chips uniformes; la corteza se deriva a calderas de biomasa para generación de vapor.', 80, 180, 2026, 'arauco-web-2026', 'arauco.com + AFCP Proceso Kraft al sulfato con recuperación química cerrada', 'alta'),
  ('kraft-p2-digestion', 'celulosa-kraft-blanqueada', 2, 'Digestión continua Kraft con licor blanco', 'reaccion', NULL, '165-170', '8-10', '[{"especie":"Chips de pino","cantidad":2.1,"unidad":"t seca/t ADt"},{"especie":"Licor blanco (NaOH + Na2S)","cantidad":null,"unidad":"m3/t ADt"}]'::jsonb, '[{"especie":"Pulpa marrón cruda (celulosa)","cantidad":1.05,"unidad":"t/t ADt"},{"especie":"Licor negro débil (lignina + reactivos)","cantidad":null,"unidad":"m3/t ADt"}]'::jsonb, '[{"especie":"Vapor de media presión","cantidad":null,"unidad":"t/t"}]'::jsonb, '[{"especie":"Trementina y tall-oil crudo","cantidad":null,"unidad":"kg/t"}]'::jsonb, NULL, 'sin_datos', 'GJ/t', 'En el digestor continuo a 168 °C, el hidróxido y sulfuro de sodio disuelven la lignina liberando las fibras largas de celulosa intactas y generando licor negro orgánico.', 360, 180, 2026, 'arauco-web-2026', 'arauco.com + AFCP Proceso Kraft al sulfato con recuperación química cerrada', 'alta'),
  ('kraft-p3-blanqueo-ecf', 'celulosa-kraft-blanqueada', 3, 'Deslignificación O2 y blanqueo ECF (ClO2/H2O2)', 'refinacion', NULL, '70-95', '3-5', '[{"especie":"Pulpa marrón lavada","cantidad":1.05,"unidad":"t/t ADt"},{"especie":"O2 + ClO2 + H2O2 + NaOH","cantidad":null,"unidad":"kg/t ADt"}]'::jsonb, '[{"especie":"Pulpa Kraft blanqueada ECF","cantidad":1,"unidad":"t ADt/t ADt"}]'::jsonb, '[{"especie":"Agua tratada de río Paraná","cantidad":null,"unidad":"m3/t"}]'::jsonb, '[{"especie":"Efluente a tratamiento biológico secundario","cantidad":null,"unidad":"m3/t"}]'::jsonb, NULL, 'sin_datos', 'MWh/t', 'La lignina residual se elimina por deslignificación con oxígeno y secuencia ECF (libre de cloro elemental) con dióxido de cloro y peróxido de hidrógeno hasta blancura >89% ISO.', 650, 120, 2026, 'arauco-web-2026', 'arauco.com + AFCP Proceso Kraft al sulfato con recuperación química cerrada', 'alta'),
  ('kraft-p4-secado-fardos', 'celulosa-kraft-blanqueada', 4, 'Formación de hoja, secado y enfardado ADt', 'producto', NULL, '110-130', '1,0', '[{"especie":"Suspensión de pulpa blanqueada","cantidad":1,"unidad":"t ADt/t ADt"}]'::jsonb, '[{"especie":"Fardos de celulosa Kraft fibra larga (90% seca)","cantidad":1,"unidad":"t ADt"}]'::jsonb, '[{"especie":"Vapor de baja presión","cantidad":null,"unidad":"t/t"}]'::jsonb, '[]'::jsonb, NULL, 'sin_datos', 'GJ/t', 'La pulpa blanqueada se drena en mesa formadora, se prensa y seca con aire caliente en túnel hasta humedad comercial (10%) formando fardos listos para papelera y exportación.', 960, 120, 2026, 'arauco-web-2026', 'arauco.com + AFCP Proceso Kraft al sulfato con recuperación química cerrada', 'alta'),
  ('kraft-p5-recuperacion-caustificacion', 'celulosa-kraft-blanqueada', 5, 'Caldera recuperadora, caustificación y horno de cal', 'separacion', 'Na2CO3 + Ca(OH)2 -> 2 NaOH + CaCO3', '900-1050', '65 (vapor cogeneración)', '[{"especie":"Licor negro concentrado (75% sólidos)","cantidad":1.5,"unidad":"t sólidos/t ADt"},{"especie":"CaO (horno de cal cerrado)","cantidad":0.25,"unidad":"t/t ADt"}]'::jsonb, '[{"especie":"Licor blanco regenerado (NaOH + Na2S)","cantidad":null,"unidad":"reciclo >96%"},{"especie":"Vapor y electricidad renovable (lignina)","cantidad":null,"unidad":"MWh/t"}]'::jsonb, '[{"especie":"Reposición Na2SO4 / CaCO3","cantidad":null,"unidad":"kg/t"}]'::jsonb, '[{"especie":"CO2 biogénico de lignina","cantidad":null,"unidad":"t/t"}]'::jsonb, NULL, 'sin_datos', 'MWh/t', 'El licor negro se quema en la caldera recuperadora generando vapor y electricidad renovable; el fundido de Na2CO3+Na2S se caustifica con cal para regenerar licor blanco hacia el digestor.', 650, 290, 2026, 'arauco-web-2026', 'arauco.com + AFCP Proceso Kraft al sulfato con recuperación química cerrada', 'alta'),
  ('glp-p1-recepcion-separacion', 'glp-fraccionamiento-austral', 1, 'Recepción offshore y separación primaria (slug catcher)', 'preparacion', NULL, '10-25', '70-85', '[{"especie":"Gas natural húmedo Cuenca Austral","cantidad":1,"unidad":"base flujo"}]'::jsonb, '[{"especie":"Gas húmedo libre de condensado","cantidad":null,"unidad":"MMm3/d"},{"especie":"Condensado crudo C5+","cantidad":null,"unidad":"m3/d"}]'::jsonb, '[{"especie":"Inhibidor de hidratos (MEG)","cantidad":null,"unidad":"kg/MMm3"}]'::jsonb, '[{"especie":"Agua de formación a tratamiento","cantidad":null,"unidad":"m3/d"}]'::jsonb, NULL, 'sin_datos', NULL, 'El gas multifásico de yacimientos offshore y costeros ingresa al slug catcher donde se separan agua libre y condensados líquidos pesados a alta presión.', 80, 180, 2026, 'eu-bref-ref', 'EU REF BREF Gas Reception & Primary Separation', 'alta'),
  ('glp-p2-deshidratacion', 'glp-fraccionamiento-austral', 2, 'Deshidratación profunda con tamices moleculares', 'preparacion', NULL, '20-30', '70', '[{"especie":"Gas húmedo C1-C5","cantidad":null,"unidad":"MMm3/d"}]'::jsonb, '[{"especie":"Gas seco (<0,1 ppmv H2O)","cantidad":null,"unidad":"MMm3/d"}]'::jsonb, '[{"especie":"Zeolita 4A (tamices regenerables)","cantidad":null,"unidad":"ciclo térmico"}]'::jsonb, '[{"especie":"Vapor de agua de regeneración","cantidad":null,"unidad":"kg/h"}]'::jsonb, NULL, 'sin_datos', NULL, 'Lechos adsorbentes de zeolitas remueven trazas de humedad por debajo de 0,1 ppmv para evitar congelamiento de hidratos en la etapa criogénica.', 340, 180, 2026, 'eu-bref-ref', 'EU REF BREF Molecular Sieve Dehydration', 'alta'),
  ('glp-p3-turboexpansion', 'glp-fraccionamiento-austral', 3, 'Enfriamiento criogénico y turbo-expansión (-95 °C)', 'separacion', NULL, '-95 a -40', '28-35', '[{"especie":"Gas seco C1-C5 a 70 bar","cantidad":null,"unidad":"MMm3/d"}]'::jsonb, '[{"especie":"Gas residual CH4 seco (a gasoducto)","cantidad":null,"unidad":"MMm3/d"},{"especie":"Corriente LGN condensada (C2-C5+)","cantidad":null,"unidad":"t/d"}]'::jsonb, '[{"especie":"Recuperación mecánica eje turbo-compresor","cantidad":null,"unidad":"MW"}]'::jsonb, '[]'::jsonb, NULL, 'sin_datos', NULL, 'La expansión isoentrópica en el turbo-expansor enfría el gas hasta -95 °C condensando propano, butanos y gasolina mientras el metano seco retorna al gasoducto troncal.', 620, 180, 2026, 'eu-bref-ref', 'EU REF BREF Cryogenic Turbo-Expander NGL Recovery', 'alta'),
  ('glp-p4-fraccionamiento', 'glp-fraccionamiento-austral', 4, 'Tren de fraccionamiento (desetanizadora, C3 y C4)', 'refinacion', NULL, '40-135', '12-26', '[{"especie":"Líquidos del gas natural (LGN)","cantidad":null,"unidad":"t/d"}]'::jsonb, '[{"especie":"Propano comercial (C3H8 >95%)","cantidad":null,"unidad":"t/d"},{"especie":"Butano comercial (C4H10)","cantidad":null,"unidad":"t/d"},{"especie":"Gasolina natural estabilizada (C5+)","cantidad":null,"unidad":"t/d"}]'::jsonb, '[{"especie":"Aceite térmico en rehervidores","cantidad":null,"unidad":"GJ/t"}]'::jsonb, '[{"especie":"Etano liviano reinyectado a gas residual","cantidad":null,"unidad":"t/d"}]'::jsonb, NULL, 'sin_datos', NULL, 'Tres columnas de destilación en serie separan por punto de ebullición el etano liviano, el propano (C3), el butano (C4) y la gasolina natural estabilizada (C5+).', 920, 140, 2026, 'eu-bref-ref', 'EU REF BREF NGL Distillation Train', 'alta'),
