  ('tan-p5-secado-spray', 'tanino-extraccion-quebracho', 5, 'Secado por atomización (spray drying)', 'producto', NULL, '160-180', '1.0', '[{"especie":"Extracto tánico concentrado","cantidad":null,"unidad":"t/t"}]'::jsonb, '[{"especie":"Extracto de quebracho en polvo (HS 3201.10)","cantidad":1,"unidad":"t/t extracto"}]'::jsonb, '[{"especie":"Aire caliente de secado","cantidad":null,"unidad":"Nm3/t"}]'::jsonb, '[]'::jsonb, NULL, 'sin_datos', NULL, 'Atomización instantánea en torre spray con ciclones y filtros de mangas obteniendo polvo homogéneo (<7% humedad) despachado en bolsas de 25 kg y big-bags.', 1220, 170, 2024, 'uncomtrade-ar-lote6-2024', 'UN Comtrade AR 2024 HS 3201.10 (11.109 t exportadas)', 'alta'),
  ('oli-p1-limpieza-molienda', 'oliva-extraccion-dos-fases', 1, 'Deshojado, lavado y molienda', 'materia_prima', NULL, '20-24', '1.0', '[{"especie":"Aceitunas frescas (Arauco, Arbequina, Picual)","cantidad":5.5,"unidad":"t/t aceite"}]'::jsonb, '[{"especie":"Pasta de aceituna molida","cantidad":5.5,"unidad":"t/t aceite"}]'::jsonb, '[{"especie":"Agua de lavado en circuito cerrado","cantidad":null,"unidad":"m3/t"}]'::jsonb, '[]'::jsonb, NULL, 'sin_datos', NULL, 'Recepción dentro de las 24 h de cosecha en Chilecito y Arauco, remoción neumática de hojas, lavado y trituración en molino de martillos de acero inoxidable.', 20, 170, 2026, 'valledelapuerta-web-2026', 'valledelapuerta.com.ar + agroaceitunera.com.ar', 'alta'),
