  ('gic-p1-desengrase-enjuague', 'galvanizado-inmersion-caliente', 1, 'Desengrase alcalino y enjuague', 'preparacion', NULL, '50-70', '1.0', '[{"especie":"Piezas y estructuras de acero negro","cantidad":null,"unidad":"t/lote"}]'::jsonb, '[{"especie":"Acero desengrasado y enjuagado","cantidad":null,"unidad":"t/lote"}]'::jsonb, '[{"especie":"Solución desengrasante alcalina","cantidad":null,"unidad":"baño"},{"especie":"Agua de enjuague industrial","cantidad":null,"unidad":"baño"}]'::jsonb, '[{"especie":"Efluente alcalino a planta de tratamiento","cantidad":null,"unidad":"m3/lote"}]'::jsonb, NULL, 'sin_datos', NULL, 'Inmersión de las piezas de acero en solución desengrasante alcalina para remover aceites y grasas de laminado o mecanizado, seguida de enjuague e inspección visual de humectabilidad.', 40, 160, 2026, 'druetta-procesos-2026', 'druetta.com.ar/galvanizado3.html: Desengrase y Enjuague', 'alta'),
  ('gic-p2-decapado-hcl', 'galvanizado-inmersion-caliente', 2, 'Decapado ácido en HCl y enjuague', 'reaccion', 'Fe2O3 + 6 HCl -> 2 FeCl3 + 3 H2O', '20-35', '1.0', '[{"especie":"Acero con calamina y óxidos (Fe2O3 / Fe3O4)","cantidad":null,"unidad":"t/lote"},{"especie":"Ácido clorhídrico (HCl acuoso)","cantidad":null,"unidad":"baño"}]'::jsonb, '[{"especie":"Acero químicamente limpio","cantidad":null,"unidad":"t/lote"}]'::jsonb, '[{"especie":"Agua de enjuague y neutralización","cantidad":null,"unidad":"baño"}]'::jsonb, '[{"especie":"Vapores ácidos HCl a torre lavadora de gases","cantidad":null,"unidad":"Nm3/h"},{"especie":"Licor ácido agotado con FeCl2/FeCl3","cantidad":null,"unidad":"m3"}]'::jsonb, NULL, 'sin_datos', NULL, 'Inmersión en solución ácida (HCl) para disolver óxidos y calamina superficiales hasta dejar el acero químicamente limpio, seguido de enjuague de neutralización y control visual.', 340, 160, 2026, 'druetta-procesos-2026', 'druetta.com.ar/galvanizado3.html + EU FMP BREF 2022', 'alta'),
