  ('gic-p4-inmersion-zinc', 'galvanizado-inmersion-caliente', 4, 'Inmersión en baño de zinc fundido (450 °C)', 'reaccion', 'Fe(s) + Zn(l, 450 °C) -> Aleación intermetálica Fe-Zn + Zn(eta)', '445-455', '1.0', '[{"especie":"Acero fluxado seco","cantidad":null,"unidad":"t/lote"},{"especie":"Zinc fundido en lingotes SHG (HS 7901.11)","cantidad":null,"unidad":"kg/t acero"}]'::jsonb, '[{"especie":"Acero con recubrimiento metalúrgico Fe-Zn","cantidad":null,"unidad":"t/lote"}]'::jsonb, '[{"especie":"Gas natural para calentamiento controlado de cuba","cantidad":null,"unidad":"Nm3/h"}]'::jsonb, '[{"especie":"Humos de NH4Cl/ZnO captados a filtro y lavador","cantidad":null,"unidad":"Nm3/h"},{"especie":"Cenizas y matas de zinc (reciclables)","cantidad":null,"unidad":"kg/t"}]'::jsonb, NULL, 'sin_datos', NULL, 'Inmersión mediante puentes grúa de 12 t en horno de zinc fundido a 450 °C (cuba principal de 13,0 x 1,8 x 3,0 m y cuba secundaria de 4,5 x 1,4 x 2,2 m con centrifugado). La difusión metalúrgica forma capas intermetálicas Fe-Zn de alta resistencia mecánica.', 940, 160, 2026, 'druetta-hornos-2026', 'druetta.com.ar/instalaciones4.html + galvanizado3.html + EU FMP BREF 2022', 'alta'),
  ('gic-p5-enfriamiento-control', 'galvanizado-inmersion-caliente', 5, 'Enfriamiento, laboratorio ISO e inspección final', 'producto', NULL, '20-45', '1.0', '[{"especie":"Acero recién galvanizado a 450 °C","cantidad":null,"unidad":"t/lote"}]'::jsonb, '[{"especie":"Estructuras y piezas de acero galvanizado certificadas","cantidad":null,"unidad":"t/lote"}]'::jsonb, '[{"especie":"Pileta de enfriamiento con agua o aire ambiente","cantidad":null,"unidad":"baño"}]'::jsonb, '[{"especie":"Agua de proceso a planta de tratamiento de efluentes","cantidad":null,"unidad":"m3"}]'::jsonb, NULL, 'sin_datos', NULL, 'Enfriamiento por inmersión en agua o a temperatura ambiente, seguido de control de espesor de capa, adherencia y aspecto visual en laboratorio propio bajo ISO 9001:2015 e ISO 14001:2015.', 1240, 160, 2026, 'druetta-web-2026', 'druetta.com.ar/galvanizado3.html + iso.html', 'alta')
