ion":"entrada","x":1044,"y":192,"dx":0,"dy":-46},{"id":"dle-agua-d301","equipo_tag":"D-301","etiqueta":"Agua lavado 85 °C","direccion":"entrada","x":1228,"y":204,"dx":0,"dy":-44}]'::jsonb, '[{"id":"dle-in-salmuera","lado":"entrada","categoria":"materia_prima","nombre":"Salmuera cruda (sin piletas largas)","formula":"LiCl (Fénix / Rincón)","cantidad_masa":"s/d m3 / t LCE","cantidad_molar":"27,06 kmol Li+ / t","fraccion_pureza":"Procesamiento en horas","corriente_num":1,"y":196,"nota":"La salmuera agotada vuelve al salar reduciendo huella hídrica.","fuente_id":"riotinto-fenix-2026"},{"id":"dle-in-soda","lado":"entrada","categoria":"materia_prima","nombre":"Ceniza de soda (Na2CO3)","formula":"Na2CO3","cantidad_masa":">= 1,434 t / t LCE","cantidad_molar":">= 13,53 kmol / t","fraccion_pureza":"Menor purga Ca/Mg por DLE","corriente_num":8,"y":356,"nota":"Estequiométrico mínimo para carbonatación.","fuente_id":"usgs-mcs-2025-litio"},{"id":"dle-out-agotada","lado":"salida","categoria":"subproducto","nombre":"Salmuera agotada + NaCl","formula":"NaCl + retorno salar","cantidad_masa":"s/d m3 + >=1,58 t NaCl/t","cantidad_molar":">= 27,06 kmol NaCl / t","fraccion_pureza":"Sin tortas masivas Mg/Ca","corriente_num":3,"y":196,"nota":"Ventaja distintiva del DLE respecto a evaporación solar.","fuente_id":"riotinto-rincon-2026"},{"id":"dle-out-lce","lado":"salida","categoria":"producto","nombre":"Carbonato de litio DLE","formula":"Li2CO3","cantidad_masa":"1,000 t / t LCE","cantidad_molar":"13,53 kmol / t LCE","fraccion_pureza":">=99,5% LCE · 18,79% Li","corriente_num":12,"y":440,"nota":"Fénix (Catamarca) 32 ktpa + Rincón (Salta) 3 -> 60 ktpa.","fuente_id":"riotinto-fenix-2026"}]'::jsonb),
  ('petroquimica-cloro-alcali-pvc', 'petroquimica', 'PFD: Electrólisis Cloro-Álcali (Membrana), EDC, MVC y Polimerización a PVC (Unipar Bahía Blanca)', 'ISO 10628 / ASME', '1,00 t de resina PVC (16,00 kmol unidad -C2H3Cl-) en Complejo Unipar Bahía Blanca', 'Complejo cloro-álcali y vinílico de Unipar Indupa en Bahía Blanca: electrólisis de salmuera NaCl ultrapura en celdas de membrana (generando Cl2, soda cáustica NaOH al 32->50% e hidrógeno H2), cloración directa y oxicloración de etileno proveniente del Polo Bahía Blanca hacia EDC, craqueo de EDC a monómero MVC con reciclo cerrado de HCl y polimerización en suspensión a PVC.', 'Consumo específico de celdas de membrana (2,5 MWh DC / t Cl2 o ECU) y estequiometría según EU Chlor-Alkali BREF (CAK). Planta operada por Unipar Indupa en Bahía Blanca.', 1880, 760, '[{"area_id":"area-100","titulo":"Área 100 · Electrólisis Cloro-Álcali","x":224,"y":40,"width":352,"height":665},{"area_id":"area-200","titulo":"Área 200 · Evaporación NaOH y Síntesis EDC","x":594,"y":40,"width":338,"height":665},{"area_id":"area-300","titulo":"Área 300 · Pirólisis EDC -> MVC","x":950,"y":40,"width":356,"height":665},{"area_id":"area-400","titulo":"Área 400 · Polimerización y Secado PVC","x":1324,"y":40,"width":332,"height":665}]'::jsonb, '[{"tag":"T-101","nombre":"Purificación salmuera (Ca/Mg)","simbolo":"column","area_id":"area-100","x":318,"y":240,"temperatura_op":"60-70 °C","presion_op":"1,0 bar","reaccion":null,"condicion_critica":"Ca/Mg < 20 ppb","descripcion":"Disolución de NaCl, precipitación química y pulido con resinas quelantes para proteger las membranas.","fuente_id":"eu-bref-chlor-alkali","cita_ubicacion":"EU CAK BREF: membrane brine purification (<20 ppb Ca+Mg)"},{"tag":"C-101","nombre":"Celdas de membrana (Cl2/NaOH)","simbolo":"electrolytic_cell","area_id":"area-100","x":502,"y":240,"temperatura_op":"85-90 °C","presion_op":"1,1 bar","reaccion":"2 NaCl + 2 H2O -> Cl2 + 2 NaOH + H2","condicion_critica":"2,5 MWh/t Cl2","descripcion":"Electrólisis BAT sin mercurio: produce Cl2 en ánodo y soda cáustica al 32% + hidrógeno H2 en cátodo.","fuente_id":"eu-bref-chlor-alkali","cita_ubicacion":"EU CAK BREF: membrane cells (2,5-3,0 MWh DC / t Cl2)"},{"tag":"V-201","nombre":"Evaporadores soda cáustica 50%","simbolo":"separator","area_id":"area-200","x":684,"y":515,"temperatura_op":"90-135 °C","presion_op":"0,2-1,0 bar","reaccion":null,"condicion_critica":"NaOH 50% comercial","descripcion":"Concentra la soda cáustica desde 32% hasta solución comercial estándar del 50% en peso para la industria química/papelera/alúmina.","fuente_id":"eu-bref-chlor-alkali","cita_ubicacion":"EU CAK BREF: caustic soda concentration to 50%"},{"tag":"R-201","nombre":"Cloración directa y oxiclor. EDC","simbolo":"reactor","area_id":"area-200","x":760,"y":240,"temperatura_op":"50-240 °C","presion_op":"1,5-5,0 bar","reaccion":"C2H4 + Cl2 -> C2H4Cl2","condicion_critica":"EDC C2H4Cl2","descripcion":"Combina Cl2 fresco y el HCl reciclado del cracker con etileno del Polo Bahía Blanca para producir 1,2-dicloroetano (EDC).","fuente_id":"unipar-acerca-2026","cita_ubicacion":"unipar.com/es/acerca-de-unipar (unidad integrada cloro -> PVC Bahía Blanca)"},{"tag":"F-301","nombre":"Horno de pirólisis EDC -> MVC","simbolo":"furnace","area_id":"area-300","x":1044,"y":240,"temperatura_op":"480-520 °C","presion_op":"20-26 bar","reaccion":"C2H4Cl2 -> C2H3Cl + HCl","condicion_critica":"TC 500 °C","descripcion":"Craqueo térmico en fase gas del EDC purificado formando monómero cloruro de vinilo (MVC) y cloruro de hidrógeno anhidro.","fuente_id":"eu-bref-lvoc-2017","cita_ubicacion":"EU LVOC BREF (2017): EDC cracking to VCM"},{"tag":"T-301","nombre":"Destilación MVC y reciclo HCl","simbolo":"column","area_id":"area-300","x":1228,"y":240,"temperatura_op":"-20 a 110 °C","presion_op":"5-12 bar","reaccion":null,"condicion_critica":"Reciclo HCl 100%","descripcion":"Separa por destilación el HCl anhidro (reciclado a oxicloración), MVC grado polímero y EDC no co